/* Léxico de palavras-chave em hebraico e grego.
   Campos: id, l (he|gr|ar), o (original), tr (transliteração), s (número de Strong),
   pt (palavras em português que costumam traduzi-la; usadas para marcar o texto), t (AT|NT|AT,NT),
   cs (true = comparar maiúsculas/minúsculas), def (sentido básico), exp (explicação), ref (textos), teo (o que estudiosos destacam). */
window.LEXICO = [
// ---------------- HEBRAICO ----------------
{id:"bereshit",l:"he",o:"בְּרֵאשִׁית",tr:"bereshit",s:"H7225",pt:["princípio"],t:"AT",
 def:"“No princípio”; de rosh, cabeça.",
 exp:"Primeira palavra da Bíblia hebraica e nome do livro de Gênesis. Reshit indica o começo e também as primícias, a parte principal. O texto não começa explicando Deus; começa com Deus já agindo.",
 ref:["Gn 1:1","Pv 8:22","Jo 1:1"],teo:"Agostinho, nas Confissões (livro XI), parte deste versículo para afirmar que o tempo foi criado junto com o mundo: não havia “antes” de Deus criar."},
{id:"bara",l:"he",o:"בָּרָא",tr:"bara",s:"H1254",pt:["criou","criados","criar","criei","cria"],t:"AT",
 def:"Criar (ação exclusivamente divina).",
 exp:"Na forma simples (qal), o sujeito de bara é sempre Deus no Antigo Testamento. O verbo nunca menciona material usado. Aparece três vezes em Gn 1: no universo (v.1), nos seres vivos (v.21) e no ser humano (v.27, três vezes num só verso).",
 ref:["Gn 1:1","Gn 1:27","Sl 51:10","Is 43:1","Is 65:17"],teo:"Davi usa o mesmo verbo ao pedir “cria em mim um coração puro” (Sl 51:10): a conversão é um ato de criação, não de reforma."},
{id:"elohim",l:"he",o:"אֱלֹהִים",tr:"Elohim",s:"H430",pt:["Deus"],t:"AT",cs:true,
 def:"Deus; forma plural usada com verbo no singular.",
 exp:"Plural de eloah. Quando se refere ao Deus de Israel, o verbo fica no singular (“criou”, não “criaram”). Gramáticos chamam isso de plural de majestade ou de plenitude. Também pode designar deuses pagãos ou juízes (Sl 82:6).",
 ref:["Gn 1:1","Gn 1:26","Sl 82:1"],teo:"Pais da Igreja como Ireneu viram no “façamos” (Gn 1:26) um indício da Trindade. Exegetas modernos preferem ler como plural deliberativo ou corte celestial; a doutrina trinitária se apoia sobretudo no NT."},
{id:"yhwh",l:"he",o:"יהוה",tr:"YHWH (Yahweh)",s:"H3068",pt:["SENHOR"],t:"AT",cs:true,
 def:"O nome pessoal de Deus, ligado a “Eu sou” (Êx 3:14).",
 exp:"O tetragrama aparece cerca de 6.800 vezes. Por reverência, os judeus passaram a ler “Adonai” (Senhor) em seu lugar; por isso as Bíblias escrevem SENHOR em maiúsculas. A forma “Jeová” vem da mistura das consoantes de YHWH com as vogais de Adonai. O nome está ligado ao verbo hayah (ser): Deus existe por si mesmo e é fiel à aliança.",
 ref:["Êx 3:14-15","Êx 6:3","Êx 34:6-7","Jo 8:58"],teo:"Tomás de Aquino viu em Êx 3:14 a base de que, em Deus, essência e existência são a mesma coisa. Teólogos bíblicos como Walther Eichrodt enfatizam o sentido relacional: “estarei convosco” (Êx 3:12)."},
{id:"adonai",l:"he",o:"אֲדֹנָי",tr:"Adonai",s:"H136",pt:["Senhor"],t:"AT",cs:true,
 def:"Meu Senhor, soberano.",
 exp:"Título de autoridade, usado também para senhores humanos na forma adon. Quando escrito “Senhor” (minúsculas), costuma traduzir Adonai; “SENHOR” traduz YHWH.",
 ref:["Gn 15:2","Sl 110:1","Is 6:1"],teo:"No Sl 110:1 (“Disse o SENHOR ao meu Senhor”), Jesus usa a diferença entre os termos para mostrar que o Messias é mais que filho de Davi (Mt 22:41-46)."},
{id:"shaddai",l:"he",o:"אֵל שַׁדַּי",tr:"El Shaddai",s:"H7706",pt:["Todo-Poderoso","Todo-poderoso","Todo Poderoso"],t:"AT",
 def:"Deus Todo-Poderoso.",
 exp:"Nome usado sobretudo com os patriarcas (Gn 17:1) e em Jó (31 vezes). A etimologia é incerta: “montanha” (shad, ligado ao acádico), “suficiente” ou “o que destrói”. A Septuaginta usa pantokratōr.",
 ref:["Gn 17:1","Êx 6:3","Jó 5:17","Ap 1:8"],teo:"Gn 17:1 liga o nome a uma exigência: “anda na minha presença e sê íntegro”. O Deus todo-suficiente chama à confiança total."},
{id:"ruach",l:"he",o:"רוּחַ",tr:"ruach",s:"H7307",pt:["espírito","Espírito","vento","fôlego"],t:"AT",
 def:"Vento, sopro, espírito.",
 exp:"A mesma palavra é vento, respiração e espírito. Em Gn 1:2, “o Espírito de Deus se movia”; em Ez 37 a ruach dá vida aos ossos secos. O grego pneuma tem o mesmo leque de sentidos.",
 ref:["Gn 1:2","Sl 104:30","Ez 37:9-14","Jl 2:28"],teo:"Jesus explora esse duplo sentido com Nicodemos: “o vento (pneuma) sopra onde quer... assim é todo aquele que é nascido do Espírito” (Jo 3:8)."},
{id:"nefesh",l:"he",o:"נֶפֶשׁ",tr:"nefesh",s:"H5315",pt:["alma"],t:"AT",
 def:"Garganta, vida, ser vivente, pessoa inteira.",
 exp:"Não é a alma imaterial do pensamento grego. Em Gn 2:7 o homem não recebe uma nefesh; ele se torna uma nefesh vivente. “Bendize, ó minha alma” (Sl 103:1) significa “bendize, todo o meu ser”.",
 ref:["Gn 2:7","Sl 42:1","Sl 103:1","Dt 6:5"],teo:"Hans Walter Wolff, em “Antropologia do Antigo Testamento”, mostrou que nefesh é o ser humano carente e desejante, que depende de Deus como a garganta depende de água."},
{id:"lev",l:"he",o:"לֵב",tr:"lev / levav",s:"H3820",pt:["coração"],t:"AT",
 def:"Coração: centro da mente, vontade e afetos.",
 exp:"Para o hebreu, o coração pensa, decide e planeja, além de sentir. Por isso “amar de todo o coração” é amar com a mente e a vontade. Endurecer o coração é decidir resistir.",
 ref:["Dt 6:5","1Sm 16:7","Pv 4:23","Jr 17:9","Ez 36:26"],teo:"Jonathan Edwards, em “Afeições Religiosas”, defendeu que a verdadeira religião consiste em grande parte em “afeições santas”, inclinações do coração que movem a vontade."},
{id:"hesed",l:"he",o:"חֶסֶד",tr:"hesed",s:"H2617",pt:["misericórdia","benignidade","bondade","benevolência"],t:"AT",
 def:"Amor leal, fidelidade de aliança, bondade que não desiste.",
 exp:"Aparece cerca de 250 vezes. Não há equivalente exato em português: junta amor, lealdade e misericórdia dentro de um compromisso. É o refrão do Sl 136 (“porque a sua benignidade dura para sempre”) e a palavra central de Rute.",
 ref:["Êx 34:6","Rt 1:8","Sl 136:1","Lm 3:22","Mq 6:8"],teo:"Nelson Glueck (1927) e Katharine Sakenfeld estudaram o termo e destacaram seu vínculo com a aliança. Muitas traduções inglesas usam steadfast love (amor firme)."},
{id:"rachamim",l:"he",o:"רַחֲמִים",tr:"rachamim",s:"H7356",pt:["misericórdias","compaixão"],t:"AT",
 def:"Compaixão profunda; da raiz rechem, útero.",
 exp:"É o amor visceral de uma mãe pelo filho que gerou. Deus é rachum, “compassivo” (Êx 34:6).",
 ref:["Is 49:15","Lm 3:22","Sl 103:13"],teo:"Phyllis Trible chamou atenção para a imagem materna na raiz da palavra. O NT expressa a mesma ideia com splanchnizomai, comover-se nas entranhas."},
{id:"emunah",l:"he",o:"אֱמוּנָה",tr:"emunah",s:"H530",pt:["fidelidade","fé"],t:"AT",
 def:"Firmeza, fidelidade, confiança.",
 exp:"Da raiz aman, “ser firme”. Indica estabilidade de caráter. Em Hc 2:4, “o justo viverá pela sua fé (fidelidade)” une confiança e perseverança.",
 ref:["Êx 17:12","Hc 2:4","Lm 3:23"],teo:"Em Êx 17:12 as mãos de Moisés ficaram “firmes” (emunah): a fé bíblica é ser sustentado de modo estável, não um sentimento passageiro."},
{id:"aman",l:"he",o:"אָמַן / אָמֵן",tr:"aman / amén",s:"H539 / H543",pt:["creu","crer","Amém","amém"],t:"AT",
 def:"Crer, apoiar-se; “amém”: é firme, assim seja.",
 exp:"Em Gn 15:6 Abraão “creu” (he'emin, apoiou-se) no SENHOR. Amém é a mesma raiz: dizer amém é declarar que algo é sólido o bastante para nos apoiarmos.",
 ref:["Gn 15:6","Is 7:9","Dt 27:15","Ap 3:14"],teo:"Is 7:9 faz um jogo de palavras com a raiz: “se não crerdes (ta'aminu), não sereis firmados (te'amenu)”. Em Ap 3:14 Jesus é chamado “o Amém”."},
{id:"shalom",l:"he",o:"שָׁלוֹם",tr:"shalom",s:"H7965",pt:["paz"],t:"AT",
 def:"Inteireza, bem-estar completo, harmonia.",
 exp:"Mais do que ausência de guerra: é tudo em seu devido lugar, com saúde, justiça, prosperidade e relações reconciliadas. Usado como saudação até hoje.",
 ref:["Nm 6:26","Is 9:6","Is 53:5","Jr 29:7"],teo:"Cornelius Plantinga, em “Não era para ser assim”, define o pecado como vandalismo do shalom."},
{id:"tsedaqah",l:"he",o:"צְדָקָה",tr:"tsedaqah",s:"H6666",pt:["justiça"],t:"AT",
 def:"Justiça: conformidade com uma norma e fidelidade nas relações.",
 exp:"A justiça de Deus no AT é sua fidelidade em agir de acordo com a aliança, o que inclui salvar o seu povo. Por isso “justiça” e “salvação” aparecem lado a lado (Is 46:13). Hoje, no hebraico moderno, tsedaqah também significa caridade.",
 ref:["Gn 15:6","Is 46:13","Am 5:24","Sl 98:2"],teo:"Para Lutero, a descoberta foi que a “justiça de Deus” em Rm 1:17 é a justiça que Deus dá ao pecador pela fé, não só a que exige. Estudiosos da Nova Perspectiva, como N. T. Wright, enfatizam também a fidelidade de Deus à aliança."},
{id:"mishpat",l:"he",o:"מִשְׁפָּט",tr:"mishpat",s:"H4941",pt:["juízo","direito"],t:"AT",
 def:"Juízo, justiça aplicada, direito, decisão justa.",
 exp:"Indica a justiça posta em prática, especialmente para quem não tem defesa: o órfão, a viúva, o estrangeiro e o pobre. Forma par com tsedaqah: “juízo e justiça”.",
 ref:["Mq 6:8","Am 5:24","Is 1:17","Jr 22:15-16"],teo:"Jr 22:16 afirma, sobre o rei Josias: “julgou a causa do aflito e do necessitado... Porventura não é isto conhecer-me?” Christopher Wright destaca: conhecer a Deus inclui praticar justiça."},
{id:"torah",l:"he",o:"תּוֹרָה",tr:"torah",s:"H8451",pt:["lei"],t:"AT",
 def:"Instrução, ensino; também a Lei de Moisés e o Pentateuco.",
 exp:"Vem de yarah, “apontar, ensinar”. É mais orientação paternal do que código penal. O Sl 119 celebra a torah como deleite.",
 ref:["Sl 1:2","Sl 119:97","Js 1:8","Dt 31:9"],teo:"Teólogos reformados falam do “terceiro uso da lei” (Calvino): além de revelar o pecado e conter o mal, a lei orienta o crente na gratidão."},
{id:"berit",l:"he",o:"בְּרִית",tr:"berit",s:"H1285",pt:["aliança","concerto","pacto"],t:"AT",
 def:"Aliança: compromisso solene que cria uma relação.",
 exp:"Fazer aliança em hebraico é “cortar” aliança (karat berit), porque animais eram cortados ao meio e as partes passavam entre eles (Gn 15; Jr 34:18). Grandes alianças: Noé, Abraão, Sinai, Davi e a Nova Aliança.",
 ref:["Gn 9:9","Gn 15:18","Êx 24:8","2Sm 7","Jr 31:31"],teo:"Em Gn 15 só Deus passa entre os animais, enquanto Abraão dorme: a aliança depende da fidelidade divina. O. Palmer Robertson, em “O Cristo dos Pactos”, define aliança como “vínculo de sangue soberanamente administrado”."},
{id:"qadosh",l:"he",o:"קָדוֹשׁ",tr:"qadosh",s:"H6918",pt:["santo","Santo","santa","santos"],t:"AT",
 def:"Santo: separado, outro, consagrado.",
 exp:"A ideia básica é separação: Deus é totalmente distinto da criação e moralmente puro. Objetos, dias e pessoas são santos quando separados para Deus.",
 ref:["Lv 19:2","Is 6:3","1Pe 1:16"],teo:"Rudolf Otto, em “O Sagrado” (1917), descreveu o santo como mysterium tremendum et fascinans. R. C. Sproul, em “A Santidade de Deus”, nota que Is 6:3 é o único atributo repetido três vezes na Bíblia."},
{id:"kavod",l:"he",o:"כָּבוֹד",tr:"kavod",s:"H3519",pt:["glória"],t:"AT",
 def:"Glória; literalmente peso.",
 exp:"Algo “pesado” tem importância e valor. A glória de Deus é o peso da sua presença manifestada, como na nuvem do tabernáculo (Êx 40:34). Honrar os pais é dar-lhes “peso” (Êx 20:12, kabbed).",
 ref:["Êx 33:18","Êx 40:34","Is 6:3","Ez 10:18"],teo:"Paulo pode ecoar esse sentido em 2Co 4:17: “eterno peso de glória”. C. S. Lewis escreveu o sermão “O Peso de Glória” (1941)."},
{id:"kipper",l:"he",o:"כִּפֶּר",tr:"kipper",s:"H3722",pt:["expiação","expiar","propiciatório"],t:"AT",
 def:"Fazer expiação: cobrir, purificar, resgatar.",
 exp:"Dá nome ao Yom Kippur (Dia da Expiação, Lv 16). O propiciatório, tampa da arca, é kapporet. O sangue “faz expiação pela vida” (Lv 17:11).",
 ref:["Lv 16:30","Lv 17:11","Êx 25:17"],teo:"Jacob Milgrom entende kipper sobretudo como purificar o santuário. Outros, como Leon Morris, destacam também a ideia de resgate (kofer) e o afastamento da ira."},
{id:"chattat",l:"he",o:"חַטָּאת",tr:"chatta't",s:"H2403",pt:["pecado","pecados"],t:"AT",
 def:"Pecado: errar o alvo; também a oferta pelo pecado.",
 exp:"O verbo chata' é usado para fundibuleiros que “não erravam” o alvo (Jz 20:16). A mesma palavra indica o pecado e o sacrifício que o remove.",
 ref:["Jz 20:16","Sl 51:2","Lv 4:3"],teo:"Paulo pode refletir esse duplo sentido em 2Co 5:21 (“o fez pecado por nós”), lido por muitos como “oferta pelo pecado”."},
{id:"avon",l:"he",o:"עָוֹן",tr:"avon",s:"H5771",pt:["iniquidade","iniquidades"],t:"AT",
 def:"Iniquidade: torção, perversidade, e também a culpa que dela resulta.",
 exp:"Indica algo torto. Pode significar o ato, a culpa e a punição. Em Is 53:6, “o SENHOR fez cair sobre ele a iniquidade de nós todos”.",
 ref:["Sl 32:5","Is 53:6","Is 53:11"],teo:"No Sl 32:5 aparecem juntos os três termos principais: pecado (chatta't), iniquidade (avon) e transgressão (pesha)."},
{id:"pesha",l:"he",o:"פֶּשַׁע",tr:"pesha",s:"H6588",pt:["transgressão","transgressões","rebelião"],t:"AT",
 def:"Transgressão: rebelião contra uma autoridade.",
 exp:"Termo político: um vassalo que rompe o tratado com o rei. Pecar, nesse sentido, é rebelar-se contra Deus.",
 ref:["Sl 51:1","Is 53:5","Am 1:3"],teo:"Amós usa “por três transgressões... e por quatro” para as nações: o pecado é revolta contra o Rei de toda a terra."},
{id:"goel",l:"he",o:"גֹּאֵל",tr:"go'el",s:"H1350",pt:["redentor","Redentor","resgatador"],t:"AT",
 def:"Parente-resgatador, vingador do sangue.",
 exp:"O parente próximo tinha o dever de comprar de volta a terra perdida, resgatar o parente vendido como escravo, gerar herdeiro para o falecido e vingar o sangue. Boaz é o go'el de Rute.",
 ref:["Lv 25:25","Rt 3:9","Jó 19:25","Is 41:14"],teo:"Em Isaías, Deus é chamado “teu Redentor” mais de 10 vezes: Ele se faz parente do seu povo. A tradição cristã vê o cumprimento na encarnação (Hb 2:14-15)."},
{id:"shuv",l:"he",o:"שׁוּב",tr:"shuv",s:"H7725",pt:["convertei-vos","convertei","voltai","volta","converter-se","arrependimento"],t:"AT",
 def:"Voltar, dar meia-volta; converter-se.",
 exp:"Um dos verbos mais frequentes do AT (mais de mil vezes). Arrepender-se é mudar de direção: voltar do mal para Deus. Deus também “volta” para o seu povo.",
 ref:["Jr 3:12-14","Ez 18:30-32","Jl 2:12-13","Ml 3:7"],teo:"William Holladay dedicou uma monografia ao verbo e mostrou como Jeremias o usa em jogos de palavras: o povo “desviado” (meshuvah) é chamado a “voltar” (shuv)."},
{id:"ahavah",l:"he",o:"אַהֲבָה",tr:"ahavah",s:"H160",pt:["amor","amarás","amei","amou"],t:"AT",
 def:"Amor (afeição e escolha).",
 exp:"Usado para o amor humano e para o amor de Deus que elege (Dt 7:7-8). O Shemá ordena “amarás”: o amor pode ser mandado porque inclui lealdade e obediência.",
 ref:["Dt 6:5","Dt 7:8","Ct 8:6","Os 11:1"],teo:"William Moran mostrou que, nos tratados antigos, “amar” o rei significava ser leal a ele. Isso ilumina o mandamento de amar a Deus."},
{id:"yada",l:"he",o:"יָדַע",tr:"yada",s:"H3045",pt:["conhecer","conheceu","conhecimento","conheço","sabereis","saberão"],t:"AT",
 def:"Conhecer por experiência e relacionamento.",
 exp:"Vai além da informação: é conhecer por convivência, até no sentido conjugal (Gn 4:1). “Conhecer o SENHOR” é ter comunhão e obediência.",
 ref:["Gn 4:1","Jr 31:34","Os 6:6","Am 3:2"],teo:"J. I. Packer, em “O Conhecimento de Deus”, insiste que conhecer a Deus é questão de relacionamento, não só de saber sobre Ele."},
{id:"mashiach",l:"he",o:"מָשִׁיחַ",tr:"mashiach",s:"H4899",pt:["ungido","Ungido","messias","Messias"],t:"AT",
 def:"Ungido. Em grego, Christos.",
 exp:"Reis, sacerdotes e às vezes profetas eram ungidos com óleo. Até Ciro, rei persa, é chamado “ungido” (Is 45:1). A esperança cresceu por um Ungido definitivo da linhagem de Davi.",
 ref:["1Sm 16:13","Sl 2:2","Is 45:1","Dn 9:25"],teo:"N. T. Wright lembra que “Cristo” não é sobrenome de Jesus: é título real, o rei de Israel prometido."},
{id:"eved",l:"he",o:"עֶבֶד",tr:"eved",s:"H5650",pt:["servo","Servo"],t:"AT",
 def:"Servo, escravo; também ministro de um rei.",
 exp:"Moisés, Davi e os profetas são “servos do SENHOR”, título de honra. Em Isaías 42–53 aparece o misterioso Servo que sofre por muitos.",
 ref:["Is 42:1","Is 49:6","Is 52:13","Is 53:11"],teo:"Bernhard Duhm (1892) isolou os quatro “Cânticos do Servo” (Is 42; 49; 50; 52:13–53:12). O NT aplica o Servo a Jesus (At 8:32-35)."},
{id:"halal",l:"he",o:"הָלַל",tr:"halal",s:"H1984",pt:["louvai","louvar","aleluia","Aleluia","louvor"],t:"AT",
 def:"Louvar, celebrar, gloriar-se.",
 exp:"Hallelu-Yah significa “louvai a Yah” (forma curta de YHWH). O nome hebraico de Salmos, Tehillim, vem da mesma raiz.",
 ref:["Sl 113:1","Sl 150","Ap 19:1-6"],teo:"Os Salmos 146–150 começam e terminam com “Aleluia”, formando o grande final do saltério."},
{id:"selah",l:"he",o:"סֶלָה",tr:"selah",s:"H5542",pt:["Selá"],t:"AT",
 def:"Termo musical de sentido incerto.",
 exp:"Aparece 71 vezes nos Salmos e 3 em Habacuque. Pode indicar pausa, interlúdio instrumental ou elevação da voz. É honesto dizer que não se sabe ao certo.",
 ref:["Sl 3:2","Sl 46:3","Hc 3:3"],teo:"Muitos pregadores tratam o Selá como convite a parar e meditar. É uma aplicação devocional, não o significado comprovado."},
{id:"tov",l:"he",o:"טוֹב",tr:"tov",s:"H2896",pt:["bom","boa","bem"],t:"AT",
 def:"Bom, belo, agradável, adequado ao propósito.",
 exp:"Refrão de Gn 1: “e viu Deus que era bom”. No fim, “muito bom” (1:31). A primeira coisa “não boa” é o homem estar só (2:18).",
 ref:["Gn 1:31","Gn 2:18","Sl 34:8"],teo:"Agostinho usou a bondade da criação contra os maniqueístas: a matéria não é má, e o mal é privação do bem (privatio boni)."},
{id:"tohu",l:"he",o:"תֹהוּ וָבֹהוּ",tr:"tohu vavohu",s:"H8414 / H922",pt:["desordenada e vazia","sem forma e vazia"],t:"AT",
 def:"Sem forma e vazia; caos inabitável.",
 exp:"Expressão rimada para o estado inicial da terra. Nos dias 1–3 Deus dá forma (separa) e nos dias 4–6 preenche. Jr 4:23 usa a mesma expressão para o juízo como “descriação”.",
 ref:["Gn 1:2","Jr 4:23","Is 45:18"],teo:"Muitos comentaristas (Wenham, Kidner) notam a simetria: dia 1 com 4, dia 2 com 5, dia 3 com 6."},
{id:"adam",l:"he",o:"אָדָם",tr:"adam",s:"H120",pt:["homem","Adão"],t:"AT",
 def:"Ser humano, humanidade; nome de Adão.",
 exp:"Jogo de palavras com adamah, “terra, solo”: o terroso, tirado do pó. Em Gn 1:27 adam inclui “macho e fêmea”.",
 ref:["Gn 1:26-27","Gn 2:7","Gn 5:2"],teo:"Paulo constrói sobre Adão a comparação com Cristo, o “último Adão” (1Co 15:45; Rm 5:12-21)."},
{id:"ezer",l:"he",o:"עֵזֶר כְּנֶגְדּוֹ",tr:"ezer kenegdo",s:"H5828",pt:["ajudadora","adjutora","auxiliadora"],t:"AT",
 def:"Ajuda correspondente; socorro “diante dele”.",
 exp:"Ezer não indica inferioridade: a palavra é usada para o próprio Deus como socorro de Israel (Sl 121:1-2; Sl 33:20). Kenegdo significa “correspondente a ele, face a face”.",
 ref:["Gn 2:18","Sl 121:1-2","Sl 33:20"],teo:"Comentaristas de várias tradições, como Victor Hamilton e John Walton, destacam que o termo descreve parceria indispensável."},
{id:"tselem",l:"he",o:"צֶלֶם / דְּמוּת",tr:"tselem / demut",s:"H6754 / H1823",pt:["imagem","semelhança"],t:"AT",
 def:"Imagem, estátua; semelhança.",
 exp:"No Antigo Oriente, reis colocavam estátuas (imagens) suas nos territórios para marcar seu domínio. Gn 1:26 democratiza a ideia: todo ser humano é imagem de Deus e representa seu governo na terra.",
 ref:["Gn 1:26-27","Gn 9:6","Cl 1:15","2Co 3:18"],teo:"Ireneu distinguiu imagem (natureza racional) de semelhança (vida espiritual). J. Richard Middleton, em “The Liberating Image”, destaca o sentido real e funcional."},
{id:"shema",l:"he",o:"שְׁמַע",tr:"shema",s:"H8085",pt:["Ouve","ouve","ouvi","Ouvi","escuta"],t:"AT",
 def:"Ouvir, escutar com atenção, obedecer.",
 exp:"Em hebraico, ouvir de verdade é obedecer. “Shemá Israel” (Dt 6:4) é a confissão diária do judaísmo. Jesus a chama de primeiro mandamento (Mc 12:29).",
 ref:["Dt 6:4","1Sm 15:22","Mc 12:29"],teo:"Na Mishná, o Shemá é recitado de manhã e à noite. O Shemá é central também para Paulo, que o reformula em 1Co 8:6 incluindo Jesus: “um só Deus, o Pai... e um só Senhor, Jesus Cristo”, como mostra Richard Bauckham."},
{id:"sheol",l:"he",o:"שְׁאוֹל",tr:"sheol",s:"H7585",pt:["inferno","mundo dos mortos"],t:"AT",
 def:"Mundo dos mortos, sepultura.",
 exp:"Lugar sombrio para onde vão todos os mortos no AT. Não é o mesmo que o inferno de punição do NT (geena). Algumas traduções antigas o traduziram como “inferno”, o que gera confusão.",
 ref:["Gn 37:35","Sl 16:10","Sl 139:8","Jn 2:2"],teo:"Pedro aplica o Sl 16:10 (“não deixarás minha alma no Sheol”) à ressurreição de Jesus (At 2:27-31)."},
{id:"navi",l:"he",o:"נָבִיא",tr:"navi",s:"H5030",pt:["profeta","profetas"],t:"AT",
 def:"Profeta: aquele que é chamado e fala em nome de Deus.",
 exp:"O profeta era sobretudo porta-voz da aliança, chamando o povo de volta à fidelidade. A predição do futuro era parte menor do seu trabalho.",
 ref:["Dt 18:18","Jr 1:9","Am 3:7"],teo:"Abraham Heschel descreveu o profeta como alguém que sente o pathos divino: compartilha do que Deus sente pelo povo."},
{id:"chokmah",l:"he",o:"חָכְמָה",tr:"chokmah",s:"H2451",pt:["sabedoria"],t:"AT",
 def:"Sabedoria: habilidade para viver bem.",
 exp:"Usada também para a habilidade de artesãos como Bezalel (Êx 31:3). Sabedoria bíblica é perícia prática de viver sob Deus, não só intelecto.",
 ref:["Êx 31:3","Pv 1:7","Pv 8:22-31","Jó 28:28"],teo:"Gerhard von Rad, em “Sabedoria em Israel”, mostra a sabedoria como confiança de que Deus pôs ordem no mundo e de que essa ordem pode ser aprendida."},
{id:"yirah",l:"he",o:"יִרְאָה",tr:"yir'ah",s:"H3374",pt:["temor"],t:"AT",
 def:"Temor: reverência que leva à obediência.",
 exp:"Inclui medo diante da grandeza de Deus e também confiança e adoração. “O temor do SENHOR é o princípio da sabedoria.”",
 ref:["Pv 1:7","Pv 9:10","Sl 111:10","Ec 12:13"],teo:"John Bunyan, em “Tratado sobre o Temor de Deus”, distingue o temor servil do temor filial, que é o de um filho que ama o pai."},
{id:"olam",l:"he",o:"עוֹלָם",tr:"olam",s:"H5769",pt:["eterno","eterna","eternamente","perpétuo","perpétua","para sempre"],t:"AT",
 def:"Longa duração, tempo distante, eternidade.",
 exp:"Indica um tempo que se perde de vista, para trás ou para frente. Aplicado a Deus significa eternidade; aplicado a instituições, “perpétuo” enquanto durar a era.",
 ref:["Gn 21:33","Sl 90:2","Ec 3:11"],teo:"Ec 3:11 diz que Deus pôs olam no coração humano: uma fome de eternidade que o tempo não satisfaz."},
{id:"shabbat",l:"he",o:"שַׁבָּת",tr:"shabbat",s:"H7676",pt:["sábado","sábados"],t:"AT",
 def:"Sábado; da raiz shavat, cessar.",
 exp:"Dia de cessar o trabalho, lembrar a criação (Êx 20:11) e a libertação do Egito (Dt 5:15). Sinal da aliança no Sinai.",
 ref:["Gn 2:2-3","Êx 20:8-11","Dt 5:15","Mc 2:27"],teo:"Abraham Heschel, em “O Sábado”, chamou o shabbat de “palácio no tempo”. Jesus afirma ser Senhor do sábado (Mc 2:28)."},
{id:"pesach",l:"he",o:"פֶּסַח",tr:"pesach",s:"H6453",pt:["Páscoa","páscoa"],t:"AT,NT",
 def:"Páscoa; de pasach, passar por cima, poupar.",
 exp:"Celebra a noite em que o anjo passou por cima das casas marcadas com sangue (Êx 12). Jesus foi crucificado durante a Páscoa.",
 ref:["Êx 12:11-13","Lc 22:15","1Co 5:7"],teo:"Melitão de Sardes (séc. II) escreveu a homilia “Sobre a Páscoa”, uma das mais antigas leituras cristãs de Êxodo 12 como figura de Cristo."},
{id:"immanuel",l:"he",o:"עִמָּנוּאֵל",tr:"Immanu'el",s:"H6005",pt:["Emanuel"],t:"AT,NT",
 def:"Deus conosco.",
 exp:"Nome do menino-sinal dado ao rei Acaz (Is 7:14). Mateus vê o cumprimento pleno em Jesus (Mt 1:23).",
 ref:["Is 7:14","Is 8:8","Mt 1:23"],teo:"A palavra almah (Is 7:14) significa jovem em idade de casar; a Septuaginta traduziu parthenos (virgem), forma que Mateus cita. Comentaristas como Motyer defendem um cumprimento pleno só em Cristo."},
{id:"yeshuah",l:"he",o:"יְשׁוּעָה",tr:"yeshu'ah",s:"H3444",pt:["salvação","livramento"],t:"AT",
 def:"Salvação, livramento, vitória.",
 exp:"Da raiz yasha, “dar espaço, livrar”. O nome Jesus (Yeshua/Yehoshua) significa “o SENHOR salva” (Mt 1:21).",
 ref:["Êx 15:2","Sl 27:1","Is 12:2","Mt 1:21"],teo:"Em Êx 14:13, “vede o livramento (yeshuah) do SENHOR” mostra a salvação como algo que Deus faz enquanto o povo fica quieto."},
{id:"davar",l:"he",o:"דָּבָר",tr:"davar",s:"H1697",pt:["palavra","Palavra"],t:"AT",
 def:"Palavra, assunto, acontecimento.",
 exp:"A palavra de Deus no AT é ativa: realiza o que diz (Is 55:11). A mesma palavra significa “coisa” e “evento”. Os “Dez Mandamentos” são, em hebraico, as “dez palavras”.",
 ref:["Gn 1:3","Sl 33:6","Is 55:11","Jr 1:9"],teo:"Este pano de fundo hebraico ajuda a ler o Logos de Jo 1: a Palavra criadora e eficaz de Gênesis se fez carne."},
{id:"hevel",l:"he",o:"הֶבֶל",tr:"hevel",s:"H1892",pt:["vaidade","vaidades"],t:"AT",
 def:"Vapor, sopro, coisa passageira.",
 exp:"Palavra-chave de Eclesiastes (38 vezes). “Vaidade de vaidades” é um superlativo: o mais passageiro de tudo. Também é o nome de Abel, cuja vida foi breve.",
 ref:["Ec 1:2","Ec 12:8","Sl 39:5","Gn 4:2"],teo:"Tremper Longman e Craig Bartholomew discutem se hevel indica sentido absurdo ou brevidade. Muitos preferem “fugaz” ou “enigmático”."},
{id:"qahal",l:"he",o:"קָהָל",tr:"qahal",s:"H6951",pt:["congregação","assembleia"],t:"AT",
 def:"Assembleia convocada.",
 exp:"O povo reunido diante de Deus, como no Sinai. A Septuaginta traduziu frequentemente por ekklēsia, palavra que o NT usa para a Igreja.",
 ref:["Dt 9:10","Dt 31:30","Sl 22:22"],teo:"Hb 2:12 cita o Sl 22:22 com ekklēsia: Cristo louva a Deus no meio da sua congregação."},
{id:"nacham",l:"he",o:"נָחַם",tr:"nacham",s:"H5162",pt:["consolai","consolar","arrependeu","arrependeu-se","consolação"],t:"AT",
 def:"Consolar; mudar de ideia, comover-se, “arrepender-se”.",
 exp:"Quando se diz que Deus “se arrependeu” (Gn 6:6; Jn 3:10), não significa que errou: indica pesar e mudança de ação diante da resposta humana. O mesmo verbo abre a consolação de Is 40:1.",
 ref:["Gn 6:6","Jn 3:10","Is 40:1","1Sm 15:29"],teo:"Calvino tratou essas expressões como acomodação: Deus fala de si de modo humano para ser compreendido. Teístas abertos, como Clark Pinnock, leram de modo mais literal; a maioria das tradições rejeita essa leitura."},
{id:"zakar",l:"he",o:"זָכַר",tr:"zakar",s:"H2142",pt:["lembrou-se","lembrou","lembra-te","lembrai-vos","memorial"],t:"AT",
 def:"Lembrar, trazer à memória e agir.",
 exp:"Quando Deus “se lembra” (Gn 8:1, de Noé), Ele age a favor. Quando o povo “se lembra”, revive e obedece.",
 ref:["Gn 8:1","Êx 2:24","Êx 20:8","Lc 22:19"],teo:"Na Ceia, “fazei isto em memória de mim” (anamnēsis) carrega esse sentido: memória que torna presente o que Deus fez, não mera recordação."},
// ---------------- GREGO ----------------
{id:"logos",l:"gr",o:"λόγος",tr:"logos",s:"G3056",pt:["Palavra","palavra"],t:"NT",
 def:"Palavra, razão, discurso, mensagem.",
 exp:"Em Jo 1:1 (que a Bíblia Livre traduz como “a Palavra”, e outras versões como “o Verbo”), o Logos é eterno, está com Deus e é Deus. Para gregos, logos era a razão que ordena o universo (Heráclito, estoicos); para judeus, a palavra criadora (davar) e a Sabedoria. João une os dois mundos.",
 ref:["Jo 1:1","Jo 1:14","Hb 4:12","Ap 19:13"],teo:"Justino Mártir (séc. II) falou de “sementes do Logos” espalhadas entre os pagãos. Atanásio, em “A Encarnação do Verbo”, mostrou que o Logos criador veio restaurar a imagem de Deus no ser humano."},
{id:"agape",l:"gr",o:"ἀγάπη",tr:"agapē",s:"G26",pt:["amor","caridade","amou","amai","amar","amado","amados"],t:"NT",
 def:"Amor que se doa, escolha de buscar o bem do outro.",
 exp:"Palavra pouco comum no grego clássico, adotada pelo NT para o amor de Deus. Em 1Co 13 é descrita por verbos: o amor faz coisas. Versões antigas traduziam por “caridade” (do latim caritas).",
 ref:["Jo 3:16","Rm 5:8","1Co 13:4-7","1Jo 4:8"],teo:"Anders Nygren (“Eros e Ágape”, 1930) opôs radicalmente os dois amores. C. S. Lewis, em “Os Quatro Amores”, foi mais nuançado. D. A. Carson, em “Os Perigos da Interpretação Bíblica”, alerta para não exagerar a diferença entre agapaō e phileō."},
{id:"phileo",l:"gr",o:"φιλέω",tr:"phileō",s:"G5368",pt:["amas","amo","amigo","amigos"],t:"NT",
 def:"Amar com afeição de amigo.",
 exp:"Relacionado a philos (amigo). Em Jo 21:15-17 Jesus pergunta a Pedro duas vezes com agapaō e na terceira com phileō.",
 ref:["Jo 5:20","Jo 11:3","Jo 15:15","Jo 21:15-17"],teo:"Muitos pregadores veem um contraste forte em Jo 21. Estudiosos como Carson e Leon Morris notam que João alterna sinônimos com frequência; o peso do texto está na tríplice pergunta que corresponde à tríplice negação."},
{id:"charis",l:"gr",o:"χάρις",tr:"charis",s:"G5485",pt:["graça"],t:"NT",
 def:"Graça: favor imerecido, dom gratuito.",
 exp:"No mundo greco-romano, charis designava favores entre patronos e clientes, que criavam obrigações de gratidão. Paulo radicaliza: a graça de Deus é dada a inimigos e sem mérito (Rm 5:8-10), e gera gratidão (eucharistia, mesma raiz).",
 ref:["Jo 1:14","Rm 3:24","Ef 2:8-9","2Co 12:9"],teo:"John Barclay, em “Paulo e o Dom” (2015), mostra que a graça em Paulo é “incongruente”: dada sem considerar o valor de quem recebe. Agostinho é conhecido como o “doutor da graça” por sua defesa contra Pelágio."},
{id:"pistis",l:"gr",o:"πίστις",tr:"pistis",s:"G4102",pt:["fé"],t:"NT",
 def:"Fé, confiança; também fidelidade.",
 exp:"O verbo é pisteuō, crer. Em João, o verbo aparece 98 vezes e o substantivo nenhuma: crer é ação. Fé inclui notitia (conhecimento), assensus (assentimento) e fiducia (confiança pessoal), como resumiram os reformadores.",
 ref:["Rm 1:17","Ef 2:8","Hb 11:1","Tg 2:17"],teo:"Há um debate sobre a expressão pistis Christou (Gl 2:16): “fé em Cristo” ou “fidelidade de Cristo”. Richard Hays defende a segunda; James Dunn, a primeira."},
{id:"dikaiosyne",l:"gr",o:"δικαιοσύνη",tr:"dikaiosynē",s:"G1343",pt:["justiça"],t:"NT",
 def:"Justiça, retidão.",
 exp:"Em Paulo, “justiça de Deus” pode ser atributo de Deus, dom dado ao crente ou a ação salvadora de Deus. Rm 1:17 e 3:21-26 são os textos centrais.",
 ref:["Mt 5:6","Rm 1:17","Rm 3:21-22","2Co 5:21","Fp 3:9"],teo:"Lutero descreveu sua descoberta (Prefácio de 1545): a justiça de Deus é aquela pela qual o justo vive pela fé, dada por Deus. Ernst Käsemann a definiu como “poder salvador de Deus”."},
{id:"dikaioo",l:"gr",o:"δικαιόω",tr:"dikaioō",s:"G1344",pt:["justificados","justificado","justifica","justificação","justificar"],t:"NT",
 def:"Justificar: declarar justo em tribunal.",
 exp:"Termo forense. Deus declara o pecador justo com base em Cristo, não em obras (Rm 3:24-28). Tiago usa o verbo no sentido de “mostrar-se justo” (Tg 2:21-24).",
 ref:["Rm 3:24","Rm 5:1","Gl 2:16","Tg 2:24"],teo:"Para a Reforma, é “o artigo pelo qual a Igreja se mantém ou cai”. O Concílio de Trento (1547) entendeu a justificação como também transformação interior. A Declaração Conjunta luterano-católica (1999) buscou consensos."},
{id:"hamartia",l:"gr",o:"ἁμαρτία",tr:"hamartia",s:"G266",pt:["pecado","pecados"],t:"NT",
 def:"Pecado; errar o alvo.",
 exp:"Equivalente ao hebraico chatta't. Em Romanos, Paulo trata o Pecado quase como um poder que domina (Rm 6–7), e não só como atos isolados.",
 ref:["Jo 1:29","Rm 3:23","Rm 6:23","1Jo 1:9"],teo:"Agostinho definiu o pecado como amor desordenado (incurvatus in se, curvado sobre si mesmo, expressão desenvolvida por Lutero)."},
{id:"metanoia",l:"gr",o:"μετάνοια",tr:"metanoia",s:"G3341",pt:["arrependimento","arrependei-vos","Arrependei-vos","arrependei","arrependam","arrependerem"],t:"NT",
 def:"Mudança de mente e de rumo.",
 exp:"De meta (mudança) e nous (mente). A Vulgata traduziu por “poenitentiam agite” (fazei penitência). Erasmo mostrou que o grego indica mudança interior, não um ato penitencial.",
 ref:["Mt 3:2","Mc 1:15","At 2:38","2Co 7:10"],teo:"A primeira das 95 teses de Lutero (1517): quando Jesus disse “arrependei-vos”, quis que toda a vida dos fiéis fosse arrependimento."},
{id:"euangelion",l:"gr",o:"εὐαγγέλιον",tr:"euangelion",s:"G2098",pt:["evangelho","Evangelho","boas novas"],t:"NT",
 def:"Boa notícia, anúncio de vitória.",
 exp:"Era usado para anúncios imperiais, como o nascimento de Augusto, celebrado na inscrição de Priene (9 a.C.) como “início das boas-novas para o mundo”. Os cristãos proclamavam outra boa-nova: Jesus é o Senhor.",
 ref:["Is 52:7","Mc 1:1","Rm 1:16","1Co 15:1-4"],teo:"Scot McKnight e N. T. Wright insistem que o evangelho é o anúncio de que Jesus é o Messias e Senhor, do qual decorre a salvação pessoal."},
{id:"ekklesia",l:"gr",o:"ἐκκλησία",tr:"ekklēsia",s:"G1577",pt:["igreja","igrejas"],t:"NT",
 def:"Assembleia; de ek (para fora) e kaleō (chamar).",
 exp:"Em Atenas era a assembleia dos cidadãos. Na Septuaginta traduz qahal, a assembleia de Israel. Indica pessoas reunidas, nunca um prédio.",
 ref:["Mt 16:18","At 2:47","Ef 5:25","1Co 1:2"],teo:"Hans Küng, em “A Igreja”, e Edmund Clowney, em “A Igreja”, destacam a continuidade com Israel: a Igreja é o povo de Deus reunido em torno de Cristo."},
{id:"koinonia",l:"gr",o:"κοινωνία",tr:"koinōnia",s:"G2842",pt:["comunhão","participação"],t:"NT",
 def:"Comunhão, participação, partilha.",
 exp:"Ter algo em comum (koinos). Inclui partilha de bens (At 2:42-44), participação em Cristo (1Co 10:16) e no Espírito (2Co 13:13).",
 ref:["At 2:42","1Co 10:16","Fp 3:10","1Jo 1:3"],teo:"Bonhoeffer, em “Vida em Comunhão”, lembra que a comunhão cristã é dom de Deus através de Cristo, não um ideal que construímos."},
{id:"christos",l:"gr",o:"Χριστός",tr:"Christos",s:"G5547",pt:["Cristo"],t:"NT",cs:true,
 def:"Ungido (= Messias).",
 exp:"Tradução grega de mashiach. “Jesus Cristo” é confissão: “Jesus é o Messias”. Em Antioquia os discípulos foram chamados “cristãos” pela primeira vez (At 11:26).",
 ref:["Mt 16:16","Jo 20:31","At 2:36"],teo:"Martin Hengel mostrou que, desde muito cedo, Christos já funcionava quase como nome próprio entre os gentios, sem perder o sentido de título."},
{id:"kyrios",l:"gr",o:"κύριος",tr:"kyrios",s:"G2962",pt:["Senhor"],t:"NT",cs:true,
 def:"Senhor, dono; usado na Septuaginta para traduzir YHWH.",
 exp:"Podia ser simples “senhor” (cortesia), mas a Septuaginta o usava para o nome divino. Confessar “Jesus é Kyrios” (Rm 10:9) aplicava a Jesus o título de Deus e desafiava o “César é Senhor”.",
 ref:["Rm 10:9","1Co 12:3","Fp 2:11","Jo 20:28"],teo:"Fp 2:10-11 aplica a Jesus Is 45:23, onde todo joelho se dobra diante de YHWH. Larry Hurtado e Richard Bauckham mostram aí a devoção a Jesus como Deus nos primeiros anos da Igreja."},
{id:"pneuma",l:"gr",o:"πνεῦμα",tr:"pneuma",s:"G4151",pt:["Espírito","espírito"],t:"NT",
 def:"Espírito, vento, sopro.",
 exp:"Equivalente a ruach. O Espírito Santo é pessoa divina que habita no crente, gera nova vida e distribui dons.",
 ref:["Jo 3:8","Jo 14:26","Rm 8:9-16","Gl 5:22"],teo:"Basílio de Cesareia, em “Sobre o Espírito Santo” (c. 375), defendeu que o Espírito deve ser adorado junto com o Pai e o Filho. Gordon Fee, em “Presença Poderosa de Deus”, estudou todas as passagens paulinas sobre o Espírito."},
{id:"sarx",l:"gr",o:"σάρξ",tr:"sarx",s:"G4561",pt:["carne"],t:"NT",
 def:"Carne: corpo, condição humana; em Paulo, também a natureza humana caída.",
 exp:"Jo 1:14 diz que a Palavra “se fez carne”, sem nada de mau. Em Paulo, “carne” muitas vezes é o ser humano voltado para si, oposto ao Espírito (Gl 5:16-17). Não equivale a “corpo físico é mau”.",
 ref:["Jo 1:14","Rm 8:3-9","Gl 5:16-24"],teo:"A NVI chegou a traduzir sarx por “natureza pecaminosa” em Paulo. Douglas Moo e James Dunn explicam que é a esfera da existência humana sem Deus."},
{id:"soma",l:"gr",o:"σῶμα",tr:"sōma",s:"G4983",pt:["corpo"],t:"NT",
 def:"Corpo.",
 exp:"Positivo em Paulo: o corpo é templo do Espírito (1Co 6:19), será ressuscitado (1Co 15:44) e a Igreja é o corpo de Cristo.",
 ref:["Rm 12:1","1Co 6:19","1Co 12:27","1Co 15:44"],teo:"Rudolf Bultmann definiu sōma como a pessoa inteira em relação. Robert Gundry respondeu que inclui o corpo físico."},
{id:"psyche",l:"gr",o:"ψυχή",tr:"psychē",s:"G5590",pt:["alma","vida"],t:"NT",
 def:"Vida, alma, pessoa.",
 exp:"Muitas vezes equivale a nefesh: a vida da pessoa. “Quem perder a sua vida (psychē) por amor de mim, achá-la-á” (Mt 16:25).",
 ref:["Mt 16:25-26","Mc 8:35","Jo 10:11","1Pe 1:9"],teo:"Oscar Cullmann, em “Imortalidade da Alma ou Ressurreição dos Mortos?”, insistiu que a esperança cristã é a ressurreição do corpo, não só a sobrevivência da alma."},
{id:"zoe",l:"gr",o:"ζωὴ αἰώνιος",tr:"zōē aiōnios",s:"G2222 / G166",pt:["vida eterna","vida"],t:"NT",
 def:"Vida eterna: vida da era vindoura.",
 exp:"Aiōnios vem de aiōn, era. Para os judeus havia esta era e a era vindoura. Em João, a vida eterna começa já agora: “esta é a vida eterna: que te conheçam” (Jo 17:3).",
 ref:["Jo 3:16","Jo 10:10","Jo 17:3","Rm 6:23"],teo:"C. H. Dodd falou de “escatologia realizada” em João; George Ladd, do “já e ainda não”: a vida da era futura já é dada, mas ainda será plena."},
{id:"soteria",l:"gr",o:"σωτηρία / σῴζω",tr:"sōtēria / sōzō",s:"G4991 / G4982",pt:["salvação","salvo","salvos","salvar","salva"],t:"NT",
 def:"Salvação; salvar, curar, livrar.",
 exp:"Sōzō é usado para curas físicas (“a tua fé te salvou”, Mc 5:34) e para a salvação eterna. A salvação tem passado (fomos salvos, Ef 2:8), presente (estamos sendo salvos, 1Co 1:18) e futuro (seremos salvos, Rm 5:9).",
 ref:["Mc 5:34","Ef 2:8","1Co 1:18","Rm 5:9"],teo:"A teologia distingue esses tempos como justificação, santificação e glorificação. John Murray, em “Redenção Consumada e Aplicada”, organizou essa ordem (ordo salutis)."},
{id:"apolytrosis",l:"gr",o:"ἀπολύτρωσις",tr:"apolytrōsis",s:"G629",pt:["redenção"],t:"NT",
 def:"Redenção: libertação mediante pagamento de resgate.",
 exp:"Lytron era o preço pago para libertar escravos ou prisioneiros. Jesus veio “dar a sua vida em resgate (lytron) de muitos” (Mc 10:45).",
 ref:["Mc 10:45","Rm 3:24","Ef 1:7","Cl 1:14"],teo:"Pais como Gregório de Nissa perguntaram a quem o resgate foi pago (ao diabo?). Anselmo, em “Por que Deus se fez homem” (1098), rejeitou essa ideia e falou de satisfação à honra de Deus."},
{id:"hilasterion",l:"gr",o:"ἱλαστήριον",tr:"hilastērion",s:"G2435",pt:["propiciação","sacrifício de reconciliação","propiciatório"],t:"NT",
 def:"Propiciação; lugar de expiação (o propiciatório).",
 exp:"Na Septuaginta é a tampa da arca (kapporet), onde o sangue era aspergido no Dia da Expiação. Em Rm 3:25 Cristo é o hilastērion. A Bíblia Livre traduz “sacrifício de reconciliação”.",
 ref:["Êx 25:17","Rm 3:25","Hb 9:5","1Jo 2:2"],teo:"C. H. Dodd (1931) defendeu “expiação” (remoção do pecado) sem ideia de ira. Leon Morris, em “A Pregação Apostólica da Cruz”, defendeu “propiciação” (desvio da ira). Muitos hoje veem as duas ideias juntas."},
{id:"katallage",l:"gr",o:"καταλλαγή",tr:"katallagē",s:"G2643",pt:["reconciliação","reconciliar","reconciliados","reconciliou"],t:"NT",
 def:"Reconciliação: troca de inimizade por amizade.",
 exp:"Termo das relações pessoais e diplomáticas. Em Paulo, é sempre Deus quem toma a iniciativa: “Deus estava em Cristo reconciliando consigo o mundo” (2Co 5:19).",
 ref:["Rm 5:10-11","2Co 5:18-20","Ef 2:16","Cl 1:20"],teo:"Ralph Martin propôs a reconciliação como centro da teologia de Paulo."},
{id:"parakletos",l:"gr",o:"παράκλητος",tr:"paraklētos",s:"G3875",pt:["Consolador","Advogado"],t:"NT",
 def:"Aquele chamado para estar ao lado: advogado, ajudador, consolador.",
 exp:"No tribunal, o paraklētos defendia alguém. Jesus promete “outro” Paráclito (Jo 14:16), ou seja, alguém como Ele próprio. Em 1Jo 2:1 o Paráclito é Jesus junto ao Pai.",
 ref:["Jo 14:16","Jo 14:26","Jo 16:7","1Jo 2:1"],teo:"Raymond Brown descreveu o Paráclito como a presença de Jesus enquanto Jesus está ausente. Agostinho usou essas passagens para mostrar a distinção pessoal do Espírito."},
{id:"parousia",l:"gr",o:"παρουσία",tr:"parousia",s:"G3952",pt:["vinda"],t:"NT",
 def:"Presença, chegada; visita oficial de um rei.",
 exp:"Termo usado para a chegada de um imperador a uma cidade, recebido por cidadãos que saíam ao seu encontro (apantēsis, 1Ts 4:17). Aplicado à segunda vinda de Cristo.",
 ref:["Mt 24:27","1Ts 4:15-17","2Pe 3:4","1Jo 2:28"],teo:"N. T. Wright e outros notam que, como numa visita imperial, os que “saem ao encontro” do Senhor voltam com Ele à terra renovada."},
{id:"apokalypsis",l:"gr",o:"ἀποκάλυψις",tr:"apokalypsis",s:"G602",pt:["revelação","manifestação"],t:"NT",
 def:"Revelação: tirar o véu.",
 exp:"Primeira palavra do último livro da Bíblia. Indica desvendar a realidade escondida, não necessariamente catástrofe. O gênero “apocalíptico” usa visões simbólicas.",
 ref:["Ap 1:1","Gl 1:12","Rm 8:19"],teo:"Richard Bauckham mostra que o Apocalipse “abre as janelas” para que as igrejas vejam o mundo do ponto de vista do trono de Deus."},
{id:"basileia",l:"gr",o:"βασιλεία",tr:"basileia",s:"G932",pt:["Reino","reino"],t:"NT",
 def:"Reino: reinado, domínio real.",
 exp:"Principalmente o exercício do governo de Deus, mais do que um território. Mateus prefere “Reino dos céus” (forma judaica reverente); os outros dizem “Reino de Deus”.",
 ref:["Mc 1:15","Mt 6:10","Lc 17:21","Rm 14:17"],teo:"George Ladd, em “O Evangelho do Reino”, popularizou o “já e ainda não”: o Reino já chegou em Jesus e virá em plenitude."},
{id:"doxa",l:"gr",o:"δόξα",tr:"doxa",s:"G1391",pt:["glória"],t:"NT",
 def:"Glória, esplendor; no grego secular, opinião ou reputação.",
 exp:"A Septuaginta usou doxa para kavod. Em João, a cruz é o lugar da glória (Jo 12:23; 17:1). Daí vem “doxologia”.",
 ref:["Jo 1:14","Jo 17:5","Rm 3:23","2Co 4:6"],teo:"Hans Urs von Balthasar construiu toda uma teologia a partir da glória (“Herrlichkeit”). Para Lutero, a “teologia da cruz” vê a glória de Deus escondida no sofrimento."},
{id:"aletheia",l:"gr",o:"ἀλήθεια",tr:"alētheia",s:"G225",pt:["verdade"],t:"NT",
 def:"Verdade; etimologicamente o que não está oculto.",
 exp:"Em João a verdade é pessoal: “Eu sou o caminho, a verdade e a vida” (14:6). Reflete também o hebraico emet: fidelidade, confiabilidade.",
 ref:["Jo 1:14","Jo 8:32","Jo 14:6","Jo 18:38"],teo:"A pergunta de Pilatos (“Que é a verdade?”) foi feita diante da Verdade em pessoa. Agostinho: “toda verdade é verdade de Deus, onde quer que se encontre” (ideia de “A Doutrina Cristã”)."},
{id:"kenoo",l:"gr",o:"κενόω",tr:"kenoō",s:"G2758",pt:["esvaziou","aniquilou"],t:"NT",
 def:"Esvaziar.",
 exp:"Fp 2:7: Cristo “esvaziou-se a si mesmo, tomando a forma de servo”. Não perdeu a divindade; abriu mão de privilégios e assumiu a humanidade.",
 ref:["Fp 2:6-8","2Co 8:9"],teo:"A “teologia kenótica” (Gottfried Thomasius, séc. XIX) afirmou que o Filho abriu mão de atributos divinos. A ortodoxia clássica (Calcedônia, Cirilo) prefere dizer que Ele assumiu a forma de servo sem deixar de ser Deus."},
{id:"hagiasmos",l:"gr",o:"ἁγιασμός / ἅγιος",tr:"hagiasmos / hagios",s:"G38 / G40",pt:["santificação","santificados","santificai","santos"],t:"NT",
 def:"Santificação; santo.",
 exp:"Todo cristão é chamado “santo” (hagios) no NT: separado para Deus. Ao mesmo tempo, é chamado a crescer em santidade.",
 ref:["1Co 1:2","1Ts 4:3","Hb 12:14","1Pe 1:15-16"],teo:"Wesley ensinou a “perfeição cristã” (amor puro, não ausência de erros). J. C. Ryle, em “Santidade”, defendeu a santificação progressiva com luta."},
{id:"eirene",l:"gr",o:"εἰρήνη",tr:"eirēnē",s:"G1515",pt:["paz"],t:"NT",
 def:"Paz.",
 exp:"Carrega o sentido do shalom. “Graça e paz” une a saudação grega (chaire/charis) e a judaica (shalom).",
 ref:["Jo 14:27","Rm 5:1","Ef 2:14","Fp 4:7"],teo:"Ef 2:14 diz que Cristo “é a nossa paz”: Ele próprio derruba o muro entre judeus e gentios."},
{id:"elpis",l:"gr",o:"ἐλπίς",tr:"elpis",s:"G1680",pt:["esperança"],t:"NT",
 def:"Esperança: expectativa confiante.",
 exp:"Não é um “talvez”. É a certeza de algo ainda futuro, garantida pela ressurreição de Cristo (1Pe 1:3).",
 ref:["Rm 5:5","Rm 8:24","1Co 13:13","1Pe 1:3"],teo:"Jürgen Moltmann, em “Teologia da Esperança” (1964), afirmou que o cristianismo é escatologia do começo ao fim."},
{id:"hypomone",l:"gr",o:"ὑπομονή",tr:"hypomonē",s:"G5281",pt:["paciência","perseverança"],t:"NT",
 def:"Perseverança: permanecer debaixo da carga.",
 exp:"De hypo (debaixo) e menō (permanecer). Resistência ativa, não resignação passiva.",
 ref:["Rm 5:3-4","Hb 12:1","Tg 1:3","Ap 13:10"],teo:"Atribui-se a João Crisóstomo a descrição da paciência perseverante como “rainha das virtudes”. William Barclay popularizou o termo como “perseverança vitoriosa”."},
{id:"makarios",l:"gr",o:"μακάριος",tr:"makarios",s:"G3107",pt:["bem-aventurados","bem-aventurado","Bem-aventurados","Benditos","bem-aventurada"],t:"NT",
 def:"Feliz, bem-aventurado, favorecido.",
 exp:"Expressa a condição de quem é aprovado por Deus, não um sentimento. Em Mt 5 descreve pessoas que o mundo não chamaria felizes. Equivale ao hebraico ashrei (Sl 1:1).",
 ref:["Sl 1:1","Mt 5:3-11","Ap 1:3"],teo:"Agostinho dedicou uma obra inteira ao Sermão do Monte e viu nas bem-aventuranças os degraus da vida cristã."},
{id:"mysterion",l:"gr",o:"μυστήριον",tr:"mystērion",s:"G3466",pt:["mistério","mistérios"],t:"NT",
 def:"Mistério: algo antes oculto, agora revelado.",
 exp:"Diferente de “enigma insolúvel”: é o plano de Deus que estava escondido e agora foi revelado, como a inclusão dos gentios (Ef 3:6).",
 ref:["Rm 16:25","Ef 3:3-6","Cl 1:26-27"],teo:"Na Vulgata, mystērion às vezes foi traduzido por sacramentum (Ef 5:32), origem do termo “sacramento”."},
{id:"nomos",l:"gr",o:"νόμος",tr:"nomos",s:"G3551",pt:["lei"],t:"NT",
 def:"Lei; geralmente a Lei de Moisés.",
 exp:"Paulo diz que a lei é santa (Rm 7:12), mas não pode justificar; revela o pecado e conduz a Cristo (Gl 3:24).",
 ref:["Rm 3:20","Rm 7:12","Gl 3:24","Rm 10:4"],teo:"E. P. Sanders (1977) argumentou que o judaísmo não era religião de mérito (“nomismo da aliança”). A partir dele se desenvolveu a Nova Perspectiva sobre Paulo."},
{id:"telos",l:"gr",o:"τετέλεσται",tr:"tetelestai",s:"G5055",pt:["consumado"],t:"NT",
 def:"Está consumado, completado.",
 exp:"Última palavra de Jesus na cruz em João (19:30), no tempo perfeito: concluído, com efeito permanente. A palavra aparece em recibos antigos em papiros, com sentido de “quitado”.",
 ref:["Jo 19:30","Jo 17:4"],teo:"Pregadores como Spurgeon trataram esta como a palavra de vitória: nada falta à obra de Cristo."},
{id:"ego_eimi",l:"gr",o:"ἐγώ εἰμι",tr:"egō eimi",s:"G1473 / G1510",pt:["Eu sou","eu sou","EU SOU"],t:"NT",
 def:"Eu sou.",
 exp:"Ecoa Êx 3:14 na Septuaginta (egō eimi ho ōn) e Is 43:10. Em Jo 8:58 (“antes que Abraão existisse, eu sou”) os ouvintes pegam pedras: entenderam como reivindicação divina.",
 ref:["Êx 3:14","Is 43:10","Jo 8:58","Jo 18:5-6"],teo:"Leon Morris e D. A. Carson leem os “Eu sou” absolutos de João como reivindicação da identidade de YHWH."},
{id:"monogenes",l:"gr",o:"μονογενής",tr:"monogenēs",s:"G3439",pt:["unigênito"],t:"NT",
 def:"Único, singular, único em sua espécie.",
 exp:"De monos (único) e genos (tipo). Hb 11:17 chama Isaque de monogenēs, embora Abraão tivesse Ismael: o sentido é “filho único e especial”.",
 ref:["Jo 1:14","Jo 1:18","Jo 3:16","Hb 11:17"],teo:"O Credo Niceno (325) usou a expressão “gerado, não criado”. Muitos léxicos modernos preferem “único”, sem negar a doutrina da geração eterna, que se apoia em outros textos."},
{id:"prototokos",l:"gr",o:"πρωτότοκος",tr:"prōtotokos",s:"G4416",pt:["primogênito"],t:"NT",
 def:"Primogênito: primeiro em ordem ou em posição.",
 exp:"Indica herdeiro e preeminência. Davi, filho mais novo, é chamado “primogênito” em Sl 89:27 por posição.",
 ref:["Sl 89:27","Rm 8:29","Cl 1:15","Cl 1:18"],teo:"Ário usou Cl 1:15 para dizer que o Filho foi criado. Atanásio respondeu: o versículo seguinte diz que nele foram criadas todas as coisas, então Ele não é uma delas."},
{id:"charisma",l:"gr",o:"χάρισμα",tr:"charisma",s:"G5486",pt:["dom","dons"],t:"NT",
 def:"Dom gratuito; presente da graça.",
 exp:"Da mesma raiz de charis. Pode ser a própria salvação (Rm 6:23) ou capacitações do Espírito para servir (1Co 12).",
 ref:["Rm 6:23","Rm 12:6","1Co 12:4-11","1Pe 4:10"],teo:"Cessacionistas (como B. B. Warfield) creem que os dons de revelação cessaram com os apóstolos. Continuístas (como Gordon Fee, Wayne Grudem e a tradição pentecostal) creem que continuam."},
{id:"baptizo",l:"gr",o:"βαπτίζω",tr:"baptizō",s:"G907",pt:["batizados","batizado","batismo","batizai","batizando"],t:"NT",
 def:"Mergulhar, imergir, lavar.",
 exp:"Usado para mergulhar tecidos em tinta ou lavar objetos. O batismo cristão simboliza união com Cristo na morte e ressurreição (Rm 6:3-4).",
 ref:["Mt 28:19","At 2:38","Rm 6:3-4","Gl 3:27"],teo:"Batistas defendem o batismo de crentes por imersão. Católicos, ortodoxos, luteranos, reformados e metodistas batizam crianças, ligando o batismo à aliança (Cl 2:11-12)."},
{id:"anastasis",l:"gr",o:"ἀνάστασις",tr:"anastasis",s:"G386",pt:["ressurreição"],t:"NT",
 def:"Ressurreição: levantar-se de novo.",
 exp:"Para os judeus, ressurreição era corporal e no fim dos tempos (Dn 12:2). O choque cristão: um homem ressuscitou no meio da história, primícias da ressurreição geral (1Co 15:20).",
 ref:["Jo 11:25","1Co 15:12-22","Fp 3:10"],teo:"N. T. Wright, em “A Ressurreição do Filho de Deus”, analisa a palavra no mundo antigo e mostra que sempre significou vida corporal depois da morte."},
{id:"martys",l:"gr",o:"μάρτυς",tr:"martys",s:"G3144",pt:["testemunha","testemunhas"],t:"NT",
 def:"Testemunha.",
 exp:"Quem testemunha o que viu. Como muitos pagaram com a vida, a palavra virou “mártir”.",
 ref:["At 1:8","At 22:20","Ap 2:13"],teo:"Tertuliano: “o sangue dos cristãos é semente” (Apologético 50), frase geralmente citada como “o sangue dos mártires é semente da Igreja”."},
{id:"skandalon",l:"gr",o:"σκάνδαλον",tr:"skandalon",s:"G4625",pt:["escândalo","tropeço","pedra de tropeço"],t:"NT",
 def:"Armadilha, pedra de tropeço.",
 exp:"Originalmente a vara que dispara uma armadilha. A cruz é “escândalo para os judeus” (1Co 1:23).",
 ref:["Mt 16:23","Rm 9:33","1Co 1:23","Gl 5:11"],teo:"Kierkegaard escreveu muito sobre a “possibilidade do escândalo”: diante de Cristo, ou se tropeça ou se crê."},
{id:"anothen",l:"gr",o:"ἄνωθεν",tr:"anōthen",s:"G509",pt:["voltar a nascer","de novo","do alto","de cima"],t:"NT",
 def:"De novo; do alto.",
 exp:"Ambiguidade proposital em Jo 3:3: Nicodemos entende “de novo” (de novo no ventre), Jesus quer dizer também “do alto”, de Deus.",
 ref:["Jo 3:3","Jo 3:7","Jo 3:31","Jo 19:11"],teo:"Raymond Brown e D. A. Carson destacam esse duplo sentido como recurso típico de João: mal-entendidos que levam a um ensino mais profundo."},
{id:"theopneustos",l:"gr",o:"θεόπνευστος",tr:"theopneustos",s:"G2315",pt:["inspirada","divinamente inspirada"],t:"NT",
 def:"Soprada por Deus.",
 exp:"Aparece só em 2Tm 3:16. A Escritura é produto do sopro de Deus, não só “inspiradora”.",
 ref:["2Tm 3:16","2Pe 1:21"],teo:"B. B. Warfield, em “A Inspiração e Autoridade da Bíblia”, mostrou que o sentido é “expirada por Deus”: vem de Deus como sua palavra."},
{id:"exousia",l:"gr",o:"ἐξουσία",tr:"exousia",s:"G1849",pt:["autoridade","poder"],t:"NT",
 def:"Autoridade, direito de agir.",
 exp:"Jesus ensinava “como quem tem autoridade” (Mt 7:29) e perdoava pecados (Mc 2:10). Toda autoridade lhe foi dada (Mt 28:18).",
 ref:["Mt 7:29","Mc 2:10","Jo 1:12","Mt 28:18"],teo:"Jo 1:12 usa exousia: aos que o receberam, deu o direito (autoridade) de serem feitos filhos de Deus."},
{id:"dynamis",l:"gr",o:"δύναμις",tr:"dynamis",s:"G1411",pt:["poder","virtude","maravilhas"],t:"NT",
 def:"Poder, força, capacidade; também milagre.",
 exp:"O evangelho é “poder (dynamis) de Deus para salvação” (Rm 1:16). Não vem daí a palavra “dinamite” no sentido bíblico: essa é uma ligação moderna sem base no texto.",
 ref:["At 1:8","Rm 1:16","1Co 1:18","2Co 12:9"],teo:"D. A. Carson usa o exemplo “dynamis = dinamite” como falácia exegética: ler o sentido de uma palavra moderna para trás no texto antigo."},
{id:"splanchnizomai",l:"gr",o:"σπλαγχνίζομαι",tr:"splanchnizomai",s:"G4697",pt:["compaixão","moveu-se de compaixão","teve compaixão","compadeceu-se"],t:"NT",
 def:"Comover-se nas entranhas; sentir compaixão profunda.",
 exp:"Splanchna são as vísceras, sede das emoções fortes. Nos evangelhos o verbo é quase só usado para Jesus e para personagens de parábolas que o representam (o pai do pródigo, o samaritano).",
 ref:["Mt 9:36","Lc 10:33","Lc 15:20","Mc 1:41"],teo:"Henri Nouwen, em “A Volta do Filho Pródigo”, medita sobre essa compaixão do pai que corre ao encontro do filho."},
{id:"teleios",l:"gr",o:"τέλειος",tr:"teleios",s:"G5046",pt:["perfeitos","perfeito","perfeição","maduros"],t:"NT",
 def:"Completo, maduro, que alcançou o propósito.",
 exp:"Vem de telos (fim, alvo). “Sede perfeitos” (Mt 5:48) indica maturidade e integridade no amor, não impecabilidade.",
 ref:["Mt 5:48","Fp 3:15","Tg 1:4","Hb 5:14"],teo:"Wesley entendeu a perfeição cristã como amor que enche o coração. Calvino ressaltou que essa perfeição é alvo para o qual sempre caminhamos."},
{id:"kosmos",l:"gr",o:"κόσμος",tr:"kosmos",s:"G2889",pt:["mundo"],t:"NT",
 def:"Mundo: ordem, universo, humanidade, sistema hostil a Deus.",
 exp:"Em João tem vários sentidos: criação (1:10), humanidade amada (3:16) e sistema em rebelião (15:18; 1Jo 2:15). Daí vem “cosmético” (adornar, ordenar).",
 ref:["Jo 1:10","Jo 3:16","Jo 15:18","1Jo 2:15"],teo:"Carson observa que em Jo 3:16 o espanto não é o mundo ser grande, mas ser mau: Deus amou o mundo rebelde."},
{id:"eucharisteo",l:"gr",o:"εὐχαριστέω",tr:"eucharisteō",s:"G2168",pt:["deu graças","dando graças","dai graças","ação de graças","agradeço"],t:"NT",
 def:"Dar graças.",
 exp:"Mesma raiz de charis: a gratidão é a resposta à graça. Deu nome à Eucaristia, porque Jesus “deu graças” ao partir o pão.",
 ref:["Lc 22:19","1Co 11:24","1Ts 5:18"],teo:"Karl Barth: “charis sempre exige eucharistia, como a voz exige o eco”."},
{id:"apostolos",l:"gr",o:"ἀπόστολος",tr:"apostolos",s:"G652",pt:["apóstolo","apóstolos"],t:"NT",
 def:"Enviado, embaixador.",
 exp:"Equivale ao hebraico shaliach: o enviado representa quem o envia. Os Doze e Paulo têm papel único como testemunhas do Ressuscitado.",
 ref:["Mc 3:14","1Co 9:1","Ef 2:20","Hb 3:1"],teo:"Hb 3:1 chama o próprio Jesus de “Apóstolo”: o Enviado do Pai."},
{id:"mathetes",l:"gr",o:"μαθητής",tr:"mathētēs",s:"G3101",pt:["discípulos","discípulo"],t:"NT",
 def:"Discípulo, aprendiz.",
 exp:"Aparece cerca de 260 vezes nos Evangelhos e Atos. Na cultura judaica, o discípulo seguia o rabi para aprender a viver como ele.",
 ref:["Mt 28:19","Lc 14:27","Jo 8:31","At 11:26"],teo:"Dallas Willard, em “A Grande Omissão”, critica a ideia de cristão que não é discípulo. Bonhoeffer: “Quando Cristo chama um homem, ordena-lhe que venha e morra.”"},
{id:"semeion",l:"gr",o:"σημεῖον",tr:"sēmeion",s:"G4592",pt:["sinal","sinais"],t:"NT",
 def:"Sinal: milagre que aponta para além de si.",
 exp:"João chama os milagres de “sinais” porque revelam quem Jesus é. São sete sinais: água em vinho, cura do filho do oficial, paralítico, multiplicação, andar sobre as águas, cego de nascença e Lázaro.",
 ref:["Jo 2:11","Jo 20:30-31","1Co 1:22"],teo:"Agostinho (Tratados sobre o Evangelho de João, 24) ensina que os milagres têm sua própria língua: é preciso perguntar o que dizem sobre Cristo, e não só admirá-los."},
{id:"hosanna",l:"gr",o:"ὡσαννά",tr:"hōsanna",s:"G5614",pt:["Hosana","hosana"],t:"NT",
 def:"“Salva, por favor!” (do hebraico hoshi'ah na).",
 exp:"Vem do Sl 118:25. Na entrada triunfal virou grito de louvor e esperança messiânica.",
 ref:["Sl 118:25-26","Mt 21:9","Jo 12:13"],teo:"Ironia notada por comentaristas: a multidão pede salvação e a recebe, mas de modo inesperado, pela cruz daquela semana."},
{id:"hades",l:"gr",o:"ᾅδης / γέεννα",tr:"hadēs / geenna",s:"G86 / G1067",pt:["inferno","Hades"],t:"NT",
 def:"Hades: mundo dos mortos. Geena: lugar de juízo final.",
 exp:"Hades corresponde ao Sheol. Geena vem do vale de Hinom, ao sul de Jerusalém, onde se haviam sacrificado crianças (Jr 7:31) e que se tornou imagem do juízo. Traduções antigas usavam “inferno” para as duas palavras.",
 ref:["Mt 5:22","Mt 16:18","Lc 16:23","Ap 20:14"],teo:"Há três visões principais entre cristãos: punição eterna consciente (tradicional), aniquilacionismo (John Stott considerou a hipótese) e universalismo (minoritário)."},
{id:"skenoo",l:"gr",o:"σκηνόω",tr:"skēnoō",s:"G4637",pt:["habitou"],t:"NT",
 def:"Armar tenda, tabernacular.",
 exp:"Jo 1:14: a Palavra “armou sua tenda” entre nós, aludindo ao tabernáculo (skēnē) do deserto, onde a glória de Deus habitava.",
 ref:["Êx 40:34","Jo 1:14","Ap 21:3"],teo:"Ap 21:3 retoma o verbo: “o tabernáculo de Deus está com os homens”. A Bíblia começa e termina com Deus habitando com seu povo."},
{id:"pleroo",l:"gr",o:"πληρόω",tr:"plēroō",s:"G4137",pt:["cumprisse","cumprir","cumpriu","cumprido","plenitude"],t:"NT",
 def:"Encher, completar, cumprir.",
 exp:"Mateus usa a fórmula “para que se cumprisse” para mostrar que Jesus completa a história e a promessa de Israel, não só predições isoladas.",
 ref:["Mt 1:22","Mt 5:17","Gl 4:4"],teo:"Em Mt 5:17 Jesus “cumpre” a Lei: leva-a ao seu alvo. R. T. France e D. A. Carson leem o verbo como plenitude escatológica."},
{id:"kainos",l:"gr",o:"καινός",tr:"kainos",s:"G2537",pt:["nova","novo","novas","novos"],t:"NT",
 def:"Novo em qualidade.",
 exp:"Diferente de neos (novo no tempo), kainos indica novidade de outro tipo: nova aliança, nova criatura, novo mandamento, novos céus e nova terra.",
 ref:["Lc 22:20","2Co 5:17","Ap 21:1-5"],teo:"Alguns linguistas acham a distinção kainos/neos exagerada em certos textos. Mesmo assim, o NT usa kainos para a novidade escatológica de Deus."},
{id:"huios_anthropou",l:"gr",o:"ὁ υἱὸς τοῦ ἀνθρώπου",tr:"ho huios tou anthrōpou",s:"G5207 / G444",pt:["Filho do homem","Filho do Homem"],t:"NT",
 def:"O Filho do Homem.",
 exp:"Título que Jesus mais usou para si (cerca de 80 vezes). Pode significar simplesmente “ser humano” (Ez 2:1), mas evoca a figura celeste de Dn 7:13-14 que recebe o Reino eterno.",
 ref:["Dn 7:13-14","Mc 10:45","Mc 14:62","Jo 1:51"],teo:"O título une humildade e glória: o Filho do Homem “não veio para ser servido, mas para servir” (Mc 10:45) e virá “sobre as nuvens” (Mc 14:62)."},
{id:"praus",l:"gr",o:"πραΰς",tr:"praus",s:"G4239",pt:["mansos","manso","mansidão"],t:"NT",
 def:"Manso: força sob controle.",
 exp:"Usado para cavalos domados: força dirigida, não fraqueza. Moisés é chamado o mais manso dos homens (Nm 12:3). Jesus é “manso e humilde de coração” (Mt 11:29).",
 ref:["Mt 5:5","Mt 11:29","Gl 5:23"],teo:"Mt 5:5 cita o Sl 37:11. Lloyd-Jones, em “Estudos no Sermão do Monte”, define mansidão como visão verdadeira de si mesmo, expressa em atitude com os outros."},
{id:"proskyneo",l:"gr",o:"προσκυνέω",tr:"proskyneō",s:"G4352",pt:["adorar","adoraram","adorarão","adoram","adorai"],t:"NT",
 def:"Adorar: prostrar-se, beijar em reverência.",
 exp:"Gesto físico de prostração diante de um rei ou deus. Jesus aceita adoração (Mt 14:33; 28:9), enquanto anjos e apóstolos a recusam (At 10:26; Ap 22:9).",
 ref:["Mt 2:11","Mt 28:17","Jo 4:23-24","Ap 5:14"],teo:"Larry Hurtado, em “Senhor Jesus Cristo”, mostra que a adoração a Jesus no culto cristão primitivo é a evidência mais forte de sua divindade reconhecida desde o início."}
];
